  ['comma-system','逗号系统','The comma system','按分句、状语、非限制修饰、同位插入和列举功能使用逗号。','Use commas by clause, adverbial, non-restrictive, appositive, parenthetical and list functions.',['comma-coordination','comma-adverbial','comma-nonrestrictive','comma-apposition-parenthetical','comma-lists']],
  ['strong-separators','强分隔符号','Stronger separators','掌握分号、冒号、破折号和括号的语法前提与信息强度。','Master the grammatical prerequisites and information strength of semicolons, colons, dashes and parentheses.',['semicolon','colon','dash-parentheses']],
  ['word-level-marks','词内标记','Word-level marks','区分所有格、缩写和复数，并按复合定语结构使用连字符。','Distinguish possessives, contractions and plurals, and hyphenate compound modifiers appropriately.',['apostrophe-possession','apostrophe-contractions','hyphens']],
  ['quotation-system','引号与直接引语','Quotation system','建立直接引语标点规则，并仅作边界识别英美风格差异。','Build direct-quotation punctuation and recognize British-American style differences only as boundaries.',['quotation-punctuation','quote-style-boundary']],
  ['capitalization-format','大小写与格式规范','Capitalization and format','处理句首、专有名称、日期节日、标题、数字和缩写。','Handle sentence starts, proper names, dates, holidays, titles, numbers and abbreviations.',['capitalization-basics','capitalization-dates-titles','numbers-abbreviations']],
  ['proofreading','综合校对','Integrated proofreading','按“句界—成对标点—词内符号—风格一致”完成综合修改。','Proofread in the order boundaries, paired marks, word-level marks and style consistency.',['integrated-proofreading']]
