function validate(course,sections){
  const ids=course.map(x=>x.id), assigned=sections.flatMap(x=>x.lessonIds);
  if(new Set(ids).size!==ids.length||assigned.length!==ids.length||new Set(assigned).size!==assigned.length||ids.some((id,i)=>assigned[i]!==id)) throw new Error('Invalid punctuation section coverage');
  if(ids[0]!=='punctuation-capitalization-essence'||!course[0].title.match(/定义|Definition/))throw new Error('Punctuation course must begin with definition and core boundaries');
  course.forEach(l=>{if(l.rules.length<3||l.examples.length!==l.rules.length||l.analyses.length!==l.rules.length||l.questions.length!==l.rules.length||l.exampleNotes.length!==l.rules.length||l.exampleNotes.some(n=>!n.visible||!n.body))throw new Error(`Incomplete punctuation lesson: ${l.id}`);l.analyses.forEach(a=>{if(!a.length||a.some(x=>!x.text||!x.role||!x.label))throw new Error(`Invalid punctuation analysis: ${l.id}`)});l.questions.forEach(q=>{if(!q.question||q.options.length!==2||!['A','B'].includes(q.answer)||!q.options.some(o=>o.key===q.answer)||!q.correct||!q.wrong)throw new Error(`Invalid punctuation question: ${l.id}`)});if(INCLUDE_RULE_COVERAGE){if(l.ruleCoverage.length!==l.rules.length)throw new Error(`Invalid punctuation coverage count: ${l.id}`);l.ruleCoverage.forEach((c,i)=>{if(c.exampleIndexes.length!==1||c.questionIndexes.length!==1||c.exampleIndexes[0]!==i||c.questionIndexes[0]!==i)throw new Error(`Invalid punctuation coverage: ${l.id}:${i}`)})}});
}
function buildPunctuationCourse(english){
  const sections=sectionSpecs.map(s=>({id:s[0],title:pick(english,s[1],s[2]),copy:pick(english,s[3],s[4]),lessonIds:s[5].slice(),lessonCount:s[5].length}));
  const rawCourse=lessonSpecs.map((s,i)=>makeLesson(english,s,i));
  const courseById=new Map(rawCourse.map((lesson)=>[lesson.id,lesson]));
  const course=sections.flatMap((section)=>section.lessonIds).map((id,index)=>Object.assign({},courseById.get(id),{no:String(index+1).padStart(2,'0')}));
  validate(course,sections);
  const core=course.filter(x=>x.level==='core'),advanced=course.filter(x=>x.level==='advanced');
  return {title:pick(english,`英语标点与大小写 · ${course.length} 节微课`,`English punctuation and capitalization · ${course.length} lessons`),copy:pick(english,'以英语句法边界为核心，系统处理句末、逗号、强分隔符、词内标记、引语、大小写和格式。','Use English syntactic boundaries to master end marks, commas, strong separators, word-level marks, quotations, capitalization and format.'),course,sections,groups:[{id:'core',title:pick(english,`核心必学 · ${core.length} 节`,`Core · ${core.length} essential lessons`),copy:pick(english,'掌握句子边界、高频标点、大小写和基本格式。','Master sentence boundaries, high-frequency punctuation, capitalization and basic format.'),lessons:core},{id:'advanced',title:pick(english,`进阶挑战 · ${advanced.length} 节`,`Advanced · ${advanced.length} challenge lessons`),copy:pick(english,'处理连字符、英美风格边界和综合校对。','Handle hyphenation, British-American style boundaries and integrated proofreading.'),lessons:advanced}]};
}
module.exports={buildPunctuationCourse};
